package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {





    @Test
    public void testCreateNumber_HexInteger() {
        // hexDigits = 4 (<= 8) -> Integer
        assertTrue(NumberUtils.createNumber("0x1234") instanceof Integer);
        // hexDigits = 10 (> 8 and <= 16) -> Long
        assertTrue(NumberUtils.createNumber("0x123456789A") instanceof Long);
        // hexDigits = 18 (> 16) -> BigInteger
        assertTrue(NumberUtils.createNumber("0x123456789ABCDEF012") instanceof BigInteger);
    }






















}

package org.apache.commons.lang3.math;

import java.io.*;
