package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {











    @Test
    public void testCreateNumber_FloatingPointPrecisions() {
        // numDecimals <= 7 -> Float
        assertTrue(NumberUtils.createNumber("1.234567") instanceof Float);
        // 7 < numDecimals <= 16 -> Double
        assertTrue(NumberUtils.createNumber("1.23456789012345") instanceof Double);
        // numDecimals > 16 -> BigDecimal
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);
    }
















}

