public class NumberUtils_createNumber_TriageGen2Test {



























    @Test
    public void testCreateNumber_ZeroPrecisionLoss() {
        // Testing the (f.floatValue() == 0.0F && !allZeros) check
        // If a number is so small it rounds to 0.0 in float, but isn't "0" string-wise, return BigDecimal
        assertTrue(NumberUtils.createNumber("0.00000000000000000000000000000000000001") instanceof BigDecimal);
    }
